"""Reviewed Obfuscate and Potence from the supplied Core PDF, not OCR guesses."""
import runpy
from pathlib import Path
base=runpy.run_path(str(Path(__file__).with_name('review-core-disciplines.py')))
def add(*args,**kwargs):
    # The supplied Conceal translation contradicts itself about cars. Keep its
    # description unpublished until the original wording or errata is supplied.
    if args[0]=='conceal':return
    return base['add'](*args,**kwargs)

add('cloak-shadows','Cloak of Shadows','Ofuscação',1,[263],[
('Descrição','Mistura-se aos arredores enquanto fica perfeitamente parado e silencioso, com alguma cobertura.'),('Custo','Gratuito.'),('Sistema','Use as regras gerais de Ofuscação. Só meios mecânicos ou sobrenaturais podem detectá-lo enquanto as condições forem mantidas. Mover-se ou ser detectado encerra o efeito.'),('Duração','Uma cena, ou até mover-se ou ser detectado.')],[
('Descrição','Blends into the surroundings while completely motionless and silent, with some cover.'),('Custo','Free.'),('Sistema','Use the general Obfuscate rules. Only mechanical or supernatural means can detect the user while the conditions hold. Moving or being detected ends the effect.'),('Duração','One scene, or until moving or detection.')])
add('silence-death','Silence of Death','Ofuscação',1,[263],[
('Descrição','Silencia os sons pessoais. Afeta somente a audição de pessoas a alcance de escuta e não engana microfones ou detectores eletrônicos; exige muito ruído para romper o silêncio.'),('Custo','Gratuito.'),('Sistema','Abafa passos, roupas, pequenas colisões e sons produzidos no próprio espaço pessoal. Fica indetectável para quem só poderia notá-lo por som, como alguém noutro andar. Não abafa sons gerados fora do espaço pessoal, como objetos arremessados ou derrubados e portas batendo. Fora essas exceções, só Sentir o Invisível detecta o usuário por esse meio.'),('Duração','Uma cena.')],[
('Descrição','Silences personal sounds. Affects only the hearing of people within earshot and does not fool microphones or electronic detectors; substantial noise is needed to break the silence.'),('Custo','Free.'),('Sistema','Muffles footsteps, clothing, minor collisions and sounds within personal space. The user is undetectable to someone who could notice them only by sound, such as a witness on another floor. It does not silence sounds generated outside personal space, such as thrown or dropped objects and slamming doors. Apart from these exceptions, only Sense the Unseen detects the user through that medium.'),('Duração','One scene.')])
add('unseen-passage','Unseen Passage','Ofuscação',2,[263],[
('Descrição','Permite movimentar-se funcionalmente invisível dentro dos limites de Ofuscação.'),('Custo','Um Teste de Sangue.'),('Sistema','Funciona automaticamente enquanto não emitir odor predominante ou som mais alto que um sussurro. Só um observador cuja atenção seja atraída pode testar detecção; Sentir o Invisível funciona normalmente. Não pode ativar para desaparecer enquanto estiver sendo observado: nesse caso falha automaticamente.'),('Duração','Uma cena ou até ser detectado.')],[
('Descrição','Allows moving about while functionally invisible within Obfuscate’s limits.'),('Custo','One Rouse Check.'),('Sistema','Works automatically while producing neither an overpowering odor nor sound louder than a whisper. Only an observer whose attention is drawn can roll for detection; Sense the Unseen works normally. It cannot be activated to disappear while observed: that attempt automatically fails.'),('Duração','One scene or until detected.')])
add('ghost-machine','Ghost in the Machine','Ofuscação',3,[263,264],[
('Descrição','Estende Ofuscação a imagens eletrônicas ao vivo. Gravações e fotos posteriores ficam indistintas, e sistemas automáticos tendem a falhar perto do usuário.'),('Custo','Nenhum custo adicional.'),('Sistema','Transmissão ao vivo não exige teste extra: trate quem observa a tela como presente no local. Aumente em 3 a Dificuldade para identificar o usuário em fotos, filmes e gravações feitos com Ofuscação ativa. Adicione 3 dados às paradas usadas para contornar vigilância eletrônica automatizada e contramedidas.'),('Duração','A do poder utilizado.')],[
('Descrição','Extends Obfuscate to live electronic images. Later recordings and photographs look indistinct, and automated systems tend to malfunction nearby.'),('Custo','No additional cost.'),('Sistema','Live transmission requires no extra roll: treat screen observers as physically present. Increase the Difficulty to identify the user in photographs, film or recordings made while Obfuscated by 3. Add 3 dice to pools used to bypass automated electronic surveillance and countermeasures.'),('Duração','As the power used.')])
add('mask-thousand','Mask of a Thousand Faces','Ofuscação',3,[264],[
('Descrição','Parece um estranho comum e esquecível, podendo interagir e falar. A presença precisa ser plausível: não engana quem não espera ninguém ou é hostil a qualquer estranho. Não fornece documentos ou meios de vencer verificação de identidade.'),('Custo','Um Teste de Sangue.'),('Sistema','Sem teste. Observadores veem um rosto comum do mesmo gênero, constituição e altura; roupas assumem neutralidade adequada ao ambiente, como vigia num escritório ou macacão numa fábrica. Sentir o Invisível penetra normalmente.'),('Duração','Uma cena.')],[
('Descrição','Appears as an ordinary, forgettable stranger while allowing interaction and speech. The presence must be plausible: it does not fool those expecting nobody or hostile to any stranger. It provides no documents or means to pass identity checks.'),('Custo','One Rouse Check.'),('Sistema','No roll. Observers see an unremarkable face of the same gender, build and height; clothes take a neutral form appropriate to the setting, such as an office security guard or factory overalls. Sense the Unseen penetrates normally.'),('Duração','One scene.')])
add('vanish','Vanish','Ofuscação',4,[264],[
('Descrição','Permite ativar Manto de Sombras ou Passagem Invisível enquanto observado e torna nebulosa a lembrança do encontro.'),('Custo','O custo do poder ampliado.'),('Parada','Raciocínio + Ofuscação contra Raciocínio + Percepção.'),('Sistema','Ao sumir diante de um mortal, uma vitória faz o observador questionar se o usuário esteve ali e embaralha a memória; um crítico apaga completamente sua lembrança. Não altera memórias de vampiros, mas qualquer vitória o oculta como se não estivesse observado. Só uma vez por cena.'),('Duração','A do poder ampliado.')],[
('Descrição','Allows activating Cloak of Shadows or Unseen Passage while observed and clouds memory of the encounter.'),('Custo','The amplified power’s cost.'),('Parada','Wits + Obfuscate opposed by Wits + Awareness.'),('Sistema','When vanishing before a mortal, a win makes the observer question whether the user was there and clouds the memory; a critical completely erases their recollection. It does not change vampire memories, but any win conceals the user as if unobserved. Only once per scene.'),('Duração','As the amplified power.')],prerequisites=['Cloak of Shadows'])
add('conceal','Conceal','Ofuscação',4,[264],[
('Descrição','Oculta objeto inanimado, como anel, porta, carro parado ou casa pequena, fazendo as pessoas ignorá-lo e contorná-lo. Colidir com o objeto ou alguém apontá-lo rompe a ilusão.'),('Custo','Um Teste de Sangue.'),('Parada','Inteligência + Ofuscação; Dificuldade 2 para anel numa gaveta cheia a 6 para casa em área aberta, conforme tamanho e localização.'),('Sistema','Toque o objeto e teste. Oculta também seu conteúdo enquanto o observador estiver do lado de fora. Não afeta algo maior que um sobrado de dois andares nem veículo em movimento. Sentir o Invisível ou equivalente pode notar o objeto com Raciocínio + Auspícios contra a Inteligência + Ofuscação do usuário.'),('Duração','Uma noite mais uma por ponto de margem.')],[
('Descrição','Hides an inanimate object such as a ring, door, parked car or small house by making people ignore and walk around it. Colliding with the object or having it pointed out breaks the illusion.'),('Custo','One Rouse Check.'),('Parada','Intelligence + Obfuscate; Difficulty 2 for a ring in a cluttered drawer to 6 for a house in the open, depending on size and location.'),('Sistema','Touch the object and roll. Also hides its contents while the observer remains outside. Cannot affect anything larger than a two-story house or a moving vehicle. Sense the Unseen or an equivalent can notice it with Wits + Auspex opposed by the user’s Intelligence + Obfuscate.'),('Duração','One night plus one per point of margin.')],{'Auspícios':3})
add('impostors-guise','Impostor’s Guise','Ofuscação',5,[265],[
('Descrição','Imita um indivíduo humano específico de qualquer gênero ou constituição, após observá-lo cuidadosamente. Não copia aparência animal.'),('Custo','Um Teste de Sangue.'),('Parada','Raciocínio + Ofuscação, Dificuldade 4, em segredo pelo Narrador; Manipulação + Performance para voz e maneirismos.'),('Sistema','Estude o rosto por pelo menos cinco minutos sob ângulos diferentes; mais dez minutos permitem estudar voz e maneirismos. Falha produz semelhança pouco convincente, percebida automaticamente por conhecidos próximos. Vitória cria ilusão convincente, mas exige Manipulação + Performance para personificar a fala e os modos. Um crítico produz ilusão perfeita sem outras rolagens. Sentir o Invisível penetra conforme as regras gerais.'),('Duração','Uma cena.')],[
('Descrição','Impersonates a specific human individual of any gender or build after careful observation. Cannot copy animal appearance.'),('Custo','One Rouse Check.'),('Parada','Wits + Obfuscate, Difficulty 4, secretly rolled by the Storyteller; Manipulation + Performance for voice and mannerisms.'),('Sistema','Study the face for at least five minutes from different angles; another ten minutes allows studying voice and mannerisms. Failure produces an unconvincing likeness automatically noticed by close acquaintances. A win creates a convincing illusion but requires Manipulation + Performance for speech and behavior. A critical creates a perfect illusion without further rolls. Sense the Unseen penetrates under the general rules.'),('Duração','One scene.')],aliases=["Impostor's Guise"],prerequisites=['Máscara de Mil Faces'])
add('cloak-gathering','Cloak the Gathering','Ofuscação',5,[265],[
('Descrição','Estende um poder conhecido de Ofuscação a companheiros voluntários.'),('Custo','Um Teste de Sangue além do custo do poder estendido; mais um alvo por Teste de Sangue adicional.'),('Sistema','Afeta um número adicional de alvos voluntários igual ao Raciocínio do usuário, ampliável como acima. Cada um conta como usuário do poder, usando a Ofuscação do vampiro quando houver teste. Todos percebem uns aos outros. Revelar um companheiro não revela os demais; revelar o usuário revela todo o grupo.'),('Duração','A do poder estendido.')],[
('Descrição','Extends one known Obfuscate power to willing companions.'),('Custo','One Rouse Check in addition to the extended power’s cost; one more target per additional Rouse Check.'),('Sistema','Affects additional willing targets equal to the user’s Wits, expandable as above. Each counts as using the power, using the vampire’s Obfuscate rating when a roll is needed. They perceive each other. Revealing a companion does not reveal the rest; revealing the user reveals the entire group.'),('Duração','As the extended power.')])
add('lethal-body','Lethal Body','Potência',1,[266],[
('Descrição','Golpes desarmados rasgam a pele e quebram ossos de mortais.'),('Custo','Gratuito.'),('Sistema','Pode causar dano agravado à Vitalidade de mortais com ataques desarmados, se desejar. Ignora um nível de armadura por ponto de Potência.'),('Duração','Passiva.')],[
('Descrição','Unarmed blows tear mortal flesh and break bones.'),('Custo','Free.'),('Sistema','May inflict Aggravated Health damage on mortals with unarmed attacks. Ignores one armor level per dot of Potence.'),('Duração','Passive.')])
add('soaring-leap','Soaring Leap','Potência',1,[266],[
('Descrição','Força sobrenatural permite saltos muito além dos limites humanos.'),('Custo','Gratuito.'),('Sistema','Salta verticalmente até três vezes Potência em metros e horizontalmente até cinco vezes Potência, sem precisar de impulso.'),('Duração','Passiva.')],[
('Descrição','Supernatural strength allows leaps far beyond human limits.'),('Custo','Free.'),('Sistema','Leaps vertically up to three times Potence in meters and horizontally up to five times Potence, with no running start.'),('Duração','Passive.')])
add('prowess','Prowess','Potência',2,[266],[
('Descrição','Amplifica a força obtida do Sangue.'),('Custo','Um Teste de Sangue.'),('Sistema','Some Potência ao dano desarmado e a feitos de Força; some metade de Potência, arredondada para cima, ao dano com Armas Brancas.'),('Duração','Uma cena.')],[
('Descrição','Amplifies the strength drawn from the Blood.'),('Custo','One Rouse Check.'),('Sistema','Add Potence to unarmed damage and feats of Strength; add half Potence, rounded up, to Melee damage.'),('Duração','One scene.')])
add('brutal-feed','Brutal Feed','Potência',3,[266],[
('Descrição','Também chamado Beijo Selvagem, drena uma vítima em segundos, muitas vezes num turno, provocando ferimentos internos destrutivos.'),('Custo','Gratuito.'),('Sistema','Cada Fome saciada causa 1 dano agravado à Vitalidade de mortal; contra vampiro, apenas superficial. Em combate, aplique primeiro o dano da mordida; depois faça até Potência ações de alimentação automaticamente bem-sucedidas. Contra vampiros, esse número cai à metade, arredondada para baixo. Armadura não protege contra a alimentação, mas protege normalmente da mordida. O Narrador pode conceder Máculas pelo assassinato mutilador.'),('Duração','Uma alimentação.')],[
('Descrição','Also called the Savage Kiss, drains a victim in seconds, often one turn, inflicting destructive internal injuries.'),('Custo','Free.'),('Sistema','Each Hunger slaked inflicts 1 Aggravated Health damage on a mortal; only Superficial damage on a vampire. In combat, apply bite damage first, then up to Potence automatically successful feeding actions. Against vampires, halve that number, rounded down. Armor does not protect against the feeding but protects normally against the bite. The Storyteller may award Stains for the mutilating killing.'),('Duração','One feeding.')],aliases=['Beijo Selvagem','Savage Kiss'])
add('spark-rage','Spark of Rage','Potência',3,[266],[
('Descrição','Combina Potência e Presença para incitar violência ou Frenesi. Uma multidão irritada pode voltar-se contra o usuário.'),('Custo','Um Teste de Sangue.'),('Parada','Manipulação + Potência contra Autocontrole + Inteligência de outro vampiro.'),('Sistema','Enquanto ativo, some Potência às tentativas de irritar ou incitar pessoa ou multidão à violência. Também pode ativar e vencer o conflito acima para obrigar outro vampiro a resistir a Frenesi de Fúria, Dificuldade 3.'),('Duração','Uma cena.')],[
('Descrição','Combines Potence and Presence to incite violence or frenzy. An enraged crowd may turn on the user.'),('Custo','One Rouse Check.'),('Parada','Manipulation + Potence opposed by another vampire’s Composure + Intelligence.'),('Sistema','While active, add Potence to attempts to anger or incite a person or crowd to violence. May also activate and win the contest above to force another vampire to resist fury frenzy at Difficulty 3.'),('Duração','One scene.')],{'Presença':3})
add('uncanny-grip','Uncanny Grip','Potência',3,[267],[
('Descrição','Crava dedos das mãos ou pés em superfícies para escalar ou ficar pendurado, deixando marcas evidentes de força bruta.'),('Custo','Um Teste de Sangue.'),('Sistema','Sucesso automático em testes de Habilidade para escalar superfícies não metálicas. Cobre, bronze e metais macios podem ser permitidos pelo Narrador. Vidro fino pode quebrar, normalmente não o de fachadas comerciais modernas. Pode permanecer pendurado numa parede ou teto por uma cena; usar os pés exige estar descalço. Rastros são detectáveis com Inteligência + Investigação, Dificuldade 2; no vidro, não exige teste.'),('Duração','Uma cena.')],[
('Descrição','Digs fingers or toes into surfaces to climb or hang, leaving obvious marks of brute force.'),('Custo','One Rouse Check.'),('Sistema','Automatically succeeds on Skill tests to climb non-metal surfaces. Copper, bronze and soft metals may be allowed by the Storyteller. Thin glass may break, generally not modern commercial facade glass. Can hang from a wall or ceiling for a scene; using feet requires being barefoot. Traces are detected with Intelligence + Investigation, Difficulty 2; traces on glass need no roll.'),('Duração','One scene.')])
add('draught-might','Draught of Might','Potência',4,[267],[
('Descrição','O Sangue transmite temporariamente parte da Potência do doador, como Elegância Direto da Fonte transmite Celeridade.'),('Custo','Um Teste de Sangue.'),('Sistema','Beber diretamente quantidade equivalente a um Teste de Sangue concede Potência igual à metade da do doador, arredondada para baixo, e os mesmos poderes dele até esse nível.'),('Duração','Uma noite; para vampiros, até a próxima alimentação ou Fome 5.')],[
('Descrição','The Blood temporarily transmits part of the donor’s Potence, as Draught of Elegance transmits Celerity.'),('Custo','One Rouse Check.'),('Sistema','Drinking directly an amount equivalent to one Rouse Check grants Potence equal to half the donor’s rating, rounded down, and their same powers up to that level.'),('Duração','One night; for vampires, until the next feeding or Hunger 5.')])
add('fist-caine','Fist of Caine','Potência',5,[267],[
('Descrição','As mãos vazias podem desmembrar, perfurar, empalar, decapitar ou arrancar o coração dos inimigos.'),('Custo','Um Teste de Sangue.'),('Sistema','Pode infligir dano agravado à Vitalidade de mortais e criaturas sobrenaturais com Briga durante a cena.'),('Duração','Uma cena.')],[
('Descrição','Bare hands can dismember, pierce, impale, decapitate or tear out an enemy’s heart.'),('Custo','One Rouse Check.'),('Sistema','May inflict Aggravated Health damage on mortals and supernatural creatures with Brawl throughout the scene.'),('Duração','One scene.')])
add('earthshock','Earthshock','Potência',5,[267],[
('Descrição','Golpeia o chão com punho ou pé para gerar uma onda de choque, com graves danos colaterais ao ambiente.'),('Custo','Dois Testes de Sangue.'),('Parada','Não exige teste do usuário. Cada pessoa num raio de até cinco metros testa Destreza + Atletismo, Dificuldade 3.'),('Sistema','Quem estiver preparado, como aliados avisados, melhora o resultado em um grau. Crítico: nenhum efeito. Vitória: perde o equilíbrio e a ação atual. Falha: cai, perde a ação atual e gasta um turno para levantar. Racha o solo, quebra móveis e espelhos; pisos acima do térreo podem desabar, derrubando os presentes ao andar inferior. Só pode ser usado uma vez por cena.'),('Duração','Um uso.')],[
('Descrição','Strikes the ground with fist or foot to create a shockwave with severe environmental collateral damage.'),('Custo','Two Rouse Checks.'),('Parada','No user roll. Everyone within up to five meters rolls Dexterity + Athletics, Difficulty 3.'),('Sistema','Prepared people, such as warned allies, improve the outcome by one step. Critical: unaffected. Win: loses balance and the current action. Failure: falls, loses the current action and spends a turn standing. Cracks earth and breaks furniture and mirrors; upper floors can collapse, dropping those present to the level below. Only usable once per scene.'),('Duração','One use.')])
